#!/bin/bash
# Acceptance sweep -> tools/accept/${ACC:-v0.4}/ (earlier sweeps stay in tools/accept/v0.2/, v0.3/). Run with GPU=1. Prints one line per check; grep FAIL. The real-path and
# bundle lines also count cdp's [EXC] lines (uncaught exceptions never reach CARD.ERRS — the bundle was dead for months
# of commits with errs [] until §11 counted them).
cd "$(dirname "$0")/.." || exit 1
export OUT=tools/accept/${ACC:-v0.4}; mkdir -p $OUT
echo "== check.js";      node tools/check.js || echo "FAIL check.js"
echo "== math tests";    node tools/test_baby.js | tail -1; node tools/test_misi.js | tail -1; node tools/test_hopf.js | tail -1; node tools/test_tempo.js | tail -1; node tools/test_director.js | tail -1; node tools/test_oklab.js | tail -1
echo "== lines smoke";    node tools/lines-smoke.js | tail -1
echo "== oklch smoke";    node tools/oklch-smoke.js | tail -1
echo "== chain smoke";    node tools/chain-smoke.js | tail -1
echo "== parity fake";   node tools/parity.js fake | grep -E "parity|MISMATCH|max \|diff\|" || echo "FAIL parity fake"
echo "== parity real";   node tools/parity.js real | tail -1
MON=$(grep -v '^//' tools/monitor.js | tr '\n' ' ' | sed 's/"/\\"/g')
echo "== monitor 60 s";  node tools/cdp.js 'test&fake=0' "[{\"wait\":1500},{\"eval\":\"$MON;'ok'\"},{\"wait\":60000},{\"eval\":\"'MON '+JSON.stringify({n:MON.n,fast:MON.fast,viol:MON.viol,errs:CARD.ERRS,bad:CARD.nonFinite()})\"}]" | grep EVAL | sed 's/.*=> //'
echo "== scenes on #test (T6 / T14)"
IDS=$(grep -ho "^  id: [0-9]*" assets/scenes/*/index.js | grep -o "[0-9]*" | sort -n)
for i in $IDS; do
  node tools/cdp.js "test&scene=$i" "[{\"wait\":6000},{\"eval\":\"'scene $i ERRS '+JSON.stringify(CARD.ERRS)+' bad '+JSON.stringify(CARD.nonFinite())+' | '+(CARD.REG[$i]?CARD.REG[$i].scene.name:'?')\"},{\"shot\":\"s$i-t6\"},{\"wait\":8200},{\"shot\":\"s$i-t14\"}]" | grep EVAL | sed 's/.*=> //'
done
# v0.2 §13/§15: a scene that samples the hist texture must shoot the same CLOCK=1 frame with the whole-texture upload (&histfull=1) and the row-delta upload
for d in $(grep -l "engineTex.hist" assets/scenes/*/index.js); do i=$(grep -o "^  id: [0-9]*" $d | grep -o "[0-9]*"); n=$(basename $(dirname $d))
  CLOCK=1 node tools/cdp.js "test&scene=$i" '[{"until":"window.CARD"},{"until":"window.__FRAME>=360"},{"shot":"hist-s'$i'-f360"},{"until":"window.__FRAME>=840"},{"shot":"hist-s'$i'-f840"}]' > /dev/null
  CLOCK=1 node tools/cdp.js "test&scene=$i&histfull=1" '[{"until":"window.CARD"},{"until":"window.__FRAME>=360"},{"shot":"hist-s'$i'-f360-full"},{"until":"window.__FRAME>=840"},{"shot":"hist-s'$i'-f840-full"}]' > /dev/null
  A=$(md5sum $OUT/hist-s$i-f360.jpg | cut -c1-32); B=$(md5sum $OUT/hist-s$i-f360-full.jpg | cut -c1-32); C=$(md5sum $OUT/hist-s$i-f840.jpg | cut -c1-32); D=$(md5sum $OUT/hist-s$i-f840-full.jpg | cut -c1-32)
  [ "$A" = "$B" ] && [ "$C" = "$D" ] && echo "hist rows == full on $n (id $i): f360 $A f840 $C" || echo "FAIL hist rows != full on $n (id $i): f360 $A/$B f840 $C/$D"
done
# v0.2 §16: FEIGEN's steady-state cost at the deepest level, tier 3, must stay at or under NAV's (interleaved in the same page; 1.5× covers the load drift) and under 2.9 ms; feigen-bench.sh writes feigen-bench-accept.txt
echo "== feigen cost";   R=$(tools/feigen-bench.sh accept 3.6 2>/dev/null | grep "^feig=3.6: L .* feigen" | head -1); F=$(echo "$R" | sed 's/.* feigen \([0-9.]*\) ms.*/\1/'); N=$(echo "$R" | sed 's/.* nav \([0-9.]*\) ms.*/\1/'); echo "$R" | cut -c1-120
[ -n "$F" ] && awk -v f="$F" -v n="$N" 'BEGIN{lim=(n*1.5>2.9)?n*1.5:2.9; if (f<=lim) print "feigen L3.6 steady " f " ms <= " lim " (nav " n ")"; else print "FAIL feigen L3.6 steady " f " ms > " lim " (nav " n ")"}' || echo "FAIL feigen-bench.sh gave no L3.6 line"
echo "== transition";  MD5=5892ddc5c1f553cbca140bbc1ef6b54d   # mixs, director-blind, re-based for the v2 colour default (v0.3 §26; 425a66e5… under the §24/§25 OKLCH default, a6e2b8cd… on the v0.2 chain, v0.2 §15): scene 0 forced, released at frame 120 with goScene(3), shot at 178 (m .499), GPU=1 1280×720. v3's crossfade byte-identical since §11; re-based from the frame-290 director pick (4ac523e9…) when FEIGEN's registration changed that pick — same pixels with FEIGEN unregistered (DECISIONS §15)
TR='{"until":"window.CARD"},{"until":"window.__FRAME>=120"},{"eval":"CARD.SC.forced=-1;CARD.goScene(3,false);CARD.SC.next"},{"until":"window.__FRAME>=178"}'
CLOCK=1 node tools/cdp.js 'test&scene=0&trans=mixs' "[$TR,{\"shot\":\"trans-mixs-0-3-f178\"}]" > /dev/null; M=$(md5sum $OUT/trans-mixs-0-3-f178.jpg | cut -c1-32); [ "$M" = "$MD5" ] && echo "mixs 0→3 f178 md5 $M = recorded" || echo "FAIL mixs 0→3 f178 md5 $M != recorded $MD5"
CLOCK=1 node tools/cdp.js 'test&scene=0&trans=morph' "[$TR,{\"shot\":\"trans-morph-0-3-f178\"},{\"eval\":\"'MORPH 0→3 f178 '+JSON.stringify({sc:[CARD.SC.cur,CARD.SC.next,+CARD.SC.m.toFixed(3)],errs:CARD.ERRS,bench:CARD.benchTransition(300)})\"}]" | grep "EVAL.*MORPH" | sed 's/.*=> //'
python3 tools/montage.py $OUT/montage-trans.jpg 2 $OUT/trans-mixs-0-3-f178.jpg $OUT/trans-morph-0-3-f178.jpg $OUT/trans-mixs-0-2-f178.jpg $OUT/trans-morph-0-2-f178.jpg $OUT/trans-mixs-1-3-f178.jpg $OUT/trans-morph-1-3-f178.jpg $OUT/trans-mixs-5-0-f178.jpg $OUT/trans-morph-5-0-f178.jpg 2>/dev/null && echo "montage $OUT/montage-trans.jpg"
echo "== hidden tab"     # v0.3 resume-hold: hide the page 15 s (a second tab activated), back → the first 60 frames fire no onset/drop/surprise, glitch 0, hit 0 (HARNESS "Hidden tab")
R=$(node tools/cdp.js 'test&fake=0&scene=6' '[{"until":"window.CARD"},{"wait":1000},{"eval":"fetch('"'"'/tools/probe.js'"'"').then(r=>r.text()).then(eval).then(()=>PROBE.start())"},{"wait":8000},{"tab":"about:blank"},{"activate":"tab"},{"wait":15000},{"activate":"main"},{"wait":3000},{"eval":"(function(){var b=PROBE.ev.filter(function(e){return e.k===\"back\"}).pop()||{t:1e9};var fr=PROBE.frames.filter(function(f){return f.t>=b.t}).slice(0,60);var r={n:fr.length,onsets:fr.filter(function(f){return f.o}).length,surprise:fr.filter(function(f){return f.s}).length,drops:PROBE.ev.filter(function(e){return e.k===\"drop\"&&e.t>=b.t}).length,gmax:Math.max.apply(null,fr.map(function(f){return f.g})),hitmax:Math.max.apply(null,fr.map(function(f){return f.hit})),resumeAt:+CARD.ENGINE.resumeAt.toFixed(1),errs:CARD.ERRS};return (r.n===60&&r.onsets+r.surprise+r.drops===0&&r.gmax===0&&r.hitmax===0&&r.resumeAt>0?\"hidden tab back \":\"FAIL hidden tab back \")+JSON.stringify(r)})()"}]' | grep EVAL | sed 's/.*=> //' | tr -d '"' | sed 's/\\//g'); echo "$R"
echo "== hidden worklet" # v0.3 §26 audit: the same on the worklet path (synapse's dnb synth, hidden 20 s at 15 s): the 150 frames back fire no surprise and the raw surprisal stays under 1.4 (before the follower snap it ramped 0.1 → 1.5 and a surprise fired at the hold's end); the demo's own surprise at ~43 s is outside the window
R=$(node tools/cdp.js 'test&fake=0&demo=dnb&scene=1' '[{"until":"window.CARD"},{"wait":1000},{"eval":"fetch('"'"'/tools/probe.js'"'"').then(r=>r.text()).then(eval).then(()=>PROBE.start())"},{"wait":14000},{"tab":"about:blank"},{"activate":"tab"},{"wait":20000},{"activate":"main"},{"wait":3000},{"eval":"(function(){var b=PROBE.ev.filter(function(e){return e.k===\"back\"}).pop()||{t:1e9};var fr=PROBE.frames.filter(function(f){return f.t>=b.t}).slice(0,150);return JSON.stringify({n:fr.length,surprise:fr.filter(function(f){return f.s}).length,drops:PROBE.ev.filter(function(e){return e.k===\"drop\"&&e.t>=b.t}).length,srMax:+Math.max.apply(null,fr.map(function(f){return f.sr})).toFixed(2),hop:CARD.ENGINE.tex.hop,resumeAt:+CARD.ENGINE.resumeAt.toFixed(1)})})()"}]' | grep EVAL | tail -1 | sed 's/.*=> //'); echo "$R"; echo "$R" | tr -d '\\' | grep -q '"n":150,"surprise":0,"drops":0,"srMax":\(0\|1\.[0-3]\)' && echo "hidden worklet: 150 frames back, 0 surprise, srMax < 1.4" || echo "FAIL hidden worklet: $R"
echo "== routes"         # v0.4: the node smokes; the view path is exact (an identity route leaves FEIGEN's f360 md5 = the reference, a real route moves it); the manual post the same way (the v2 default's own bloom thr = identical, bloom off moves it); the panel opened (key p) then closed before the shot leaves the canvas md5 identical; a panel-open shot for the eyes
node tools/route-smoke.js | tail -1; node tools/manual-smoke.js | tail -1
REF6=$(grep "s6-f360" tools/accept/v0.4/scene-md5-v03.txt | cut -c1-32)
for r in "route-id:route=feigen.bass=bass:same" "route-hi:route=feigen.bass=high:diff" "post-same:post=feigen.bloom.thr=0.3:same" "post-off:post=feigen.bloom.thr=2:diff"; do t=${r%%:*}; q=${r#*:}; q=${q%:*}; want=${r##*:}
  CLOCK=1 node tools/cdp.js "test&scene=6&$q" "[{\"until\":\"window.CARD\"},{\"until\":\"window.__FRAME>=360\"},{\"shot\":\"$t-s6-f360\"}]" > /dev/null; M=$(md5sum $OUT/$t-s6-f360.jpg | cut -c1-32)
  if [ "$want" = same ]; then [ "$M" = "$REF6" ] && echo "$t: s6 f360 md5 = reference ($M)" || echo "FAIL $t: s6 f360 md5 $M != reference $REF6"; else [ "$M" != "$REF6" ] && echo "$t: s6 f360 md5 $M != reference (moved, as it must)" || echo "FAIL $t: s6 f360 md5 did not move"; fi
done
R=$(CLOCK=1 node tools/cdp.js 'test&scene=6' '[{"until":"window.CARD"},{"key":"p"},{"until":"window.__FRAME>=300"},{"eval":"'"'"'panel open: on '"'"'+CARD.HELP.on+'"'"' E '"'"'+!!document.getElementById('"'"'helpE'"'"')+'"'"' n '"'"'+CARD.ROUTE.n+'"'"' ticks '"'"'+CARD.HELP.ticks"},{"key":"Escape"},{"until":"window.__FRAME>=360"},{"shot":"panel-closed-s6-f360"}]'); echo "$R" | grep EVAL | sed 's/.*=> //' | tr -d '"'; M=$(md5sum $OUT/panel-closed-s6-f360.jpg | cut -c1-32); [ "$M" = "$REF6" ] && echo "panel opened then closed: s6 f360 md5 = reference" || echo "FAIL panel opened then closed: s6 f360 md5 $M != $REF6"
CLOCK=1 node tools/cdp.js 'test' '[{"until":"window.CARD"},{"key":"p"},{"until":"window.__FRAME>=120"},{"shot":"panel-s0-f120"},{"eval":"'"'"'panel shot: scrollTop '"'"'+document.getElementById('"'"'help'"'"').scrollTop+'"'"' rows '"'"'+CARD.HELP.rows().length+'"'"' errs '"'"'+JSON.stringify(CARD.ERRS)"}]' | grep EVAL | sed 's/.*=> //' | tr -d '"'
# v0.4.1 panel-legibility: a preview is a route for 2 s of help ticks then the previous route back, storage untouched; Escape mid-preview puts it back at once (closeE); force/release move MANUAL.scene
R=$(CLOCK=1 node tools/cdp.js 'test&scene=6&route=feigen.bass=centroid*1.5' '[{"until":"window.CARD"},{"key":"p"},{"until":"window.__FRAME>=120"},{"eval":"document.getElementById('"'"'pe-p1-feigen-bass'"'"').click();1"},{"until":"window.__FRAME>=150"},{"eval":"'"'"'PREVIEW f150 '"'"'+CARD.ROUTES.feigen.bass.src+'"'"' c '"'"'+CARD.ROUTES.feigen.bass.c"},{"until":"window.__FRAME>=300"},{"eval":"'"'"'PREVIEW f300 '"'"'+CARD.ROUTES.feigen.bass.src+'"'"' k '"'"'+CARD.ROUTES.feigen.bass.k+'"'"' n '"'"'+CARD.ROUTE.n+'"'"' store '"'"'+localStorage.getItem('"'"'ew.routes.v1'"'"')"},{"eval":"document.getElementById('"'"'pe-p0-feigen-bass'"'"').click();1"},{"until":"window.__FRAME>=310"},{"key":"Escape"},{"until":"window.__FRAME>=320"},{"eval":"'"'"'CLOSE f320 '"'"'+CARD.ROUTES.feigen.bass.src+'"'"' help '"'"'+CARD.HELP.on"}]'); echo "$R" | grep EVAL | sed 's/.*=> //' | tr -d '"'
echo "$R" | grep -q "PREVIEW f150 const c 1" && echo "$R" | grep -q "PREVIEW f300 centroid k 1.5 n 1 store null" && echo "$R" | grep -q "CLOSE f320 centroid help false" && echo "preview: const at f150, centroid*1.5 back at f300, storage null, Escape mid-preview restores" || echo "FAIL preview sequence"
R=$(CLOCK=1 node tools/cdp.js 'test' '[{"until":"window.CARD"},{"key":"p"},{"until":"window.__FRAME>=120"},{"eval":"document.getElementById('"'"'pe-force'"'"').click();'"'"'FORCE '"'"'+(CARD.MANUAL.scene===CARD.SC.logical)+'"'"' '"'"'+document.getElementById('"'"'pe-force-line'"'"').textContent.slice(0,20)"},{"eval":"document.getElementById('"'"'pe-release'"'"').click();'"'"'RELEASE '"'"'+CARD.MANUAL.scene"}]'); echo "$R" | grep EVAL | sed 's/.*=> //' | tr -d '"'; echo "$R" | grep -q "FORCE true" && echo "$R" | grep -q "RELEASE -1" && echo "force/release: ok" || echo "FAIL force/release"
echo "== help"           # v0.2 §12: two shots with the help open (NAV f120, TORUS f360 — the fake timeline's first switch is at 233), the cast scrolled, coverage by eval, ticks hidden/open, the real path with the help opened and closed
CLOCK=1 node tools/cdp.js 'test' '[{"until":"window.CARD"},{"key":"h"},{"until":"window.__FRAME>=120"},{"shot":"help-s0-f120"},{"until":"window.__FRAME>=360"},{"shot":"help-s3-f360"},{"eval":"document.getElementById('"'"'help'"'"').scrollTop=1e5;'"'"'help cast shot scrolled to '"'"'+document.getElementById('"'"'help'"'"').scrollTop"},{"shot":"help-cast"},{"eval":"(function(){var out=[],ok=0,n=0,all=Object.keys(CARD.FEATS).filter(function(k){return CARD.FEATS[k].kind!==\"internal\"}).length,rows=0,uniq=0;for(var i=0;i<CARD.REG.length;i++){var E=CARD.REG[i];if(!E)continue;n++;CARD.goScene(E.id,true);var t=CARD.HELP.rows(true),r=CARD.HELP.rows(),f=E.scene.feats;rows=r.length;uniq=new Set(r).size;if(t.slice().sort().join()===f.slice().sort().join())ok++;else out.push(\"id \"+E.id+\" top!=feats\")}return \"help fields \"+rows+\"/\"+all+\" (unique \"+uniq+\") · top table = feats on \"+ok+\"/\"+n+\" ids\"+(out.length?\" FAIL \"+out.join(\",\"):\"\")})()"}]' | grep EVAL | sed 's/.*=> //' | tr -d '"'
CLOCK=1 node tools/cdp.js 'test' '[{"until":"window.CARD"},{"until":"window.__FRAME>=600"},{"eval":"'"'"'help ticks hidden '"'"'+CARD.HELP.ticks+'"'"' (600 frames, want 0)'"'"'"},{"key":"h"},{"until":"window.__FRAME>=1200"},{"eval":"'"'"'help ticks open '"'"'+CARD.HELP.ticks+'"'"' (600 frames, want 100) errs '"'"'+JSON.stringify(CARD.ERRS)"}]' | grep EVAL | sed 's/.*=> //' | tr -d '"'
R=$(NOAUTO=1 node tools/cdp.js 'real' '[{"wait":1500},{"click":[695,440]},{"wait":3000},{"key":"h"},{"wait":1500},{"shot":"help-real"},{"key":"Escape"},{"wait":1500},{"eval":"'"'"'HELP real '"'"'+JSON.stringify({on:CARD.HELP.on,ticks:CARD.HELP.ticks,bad:CARD.nonFinite(),errs:CARD.ERRS})"}]'); echo "$R" | grep EVAL | sed 's/.*=> //'; N=$(echo "$R" | grep -c '^\[EXC\]'); [ "$N" = 0 ] && echo "exceptions 0" || { echo "FAIL $N uncaught exceptions with the help open"; echo "$R" | grep '^\[EXC\]' | head -1 | cut -c1-300; }
echo "== real start path"
R=$(NOAUTO=1 node tools/cdp.js 'real' '[{"wait":1500},{"shot":"real-landing"},{"click":[695,440]},{"wait":4000},{"eval":"'"'"'REAL '"'"'+JSON.stringify({mode:CARD.ENGINE.AU.mode,bad:CARD.nonFinite(),errs:CARD.ERRS,glerr:CARD.glerr})"},{"shot":"real-4s"},{"wait":20000},{"eval":"'"'"'REAL24 '"'"'+JSON.stringify({bad:CARD.nonFinite(),errs:CARD.ERRS,switched:CARD.SC.hist.length>1})"},{"shot":"real-24s"}]'); echo "$R" | grep EVAL | sed 's/.*=> //'; N=$(echo "$R" | grep -c '^\[EXC\]'); [ "$N" = 0 ] && echo "exceptions 0" || { echo "FAIL $N uncaught exceptions"; echo "$R" | grep '^\[EXC\]' | head -1 | cut -c1-300; }
echo "== bundle";        node tools/bundle.js && R=$(FILE=$PWD/dist/eigenwobble.html NOAUTO=1 node tools/cdp.js 'real' '[{"wait":1500},{"click":[695,440]},{"wait":3000},{"key":"h"},{"wait":1500},{"key":"Escape"},{"wait":25500},{"eval":"'"'"'BUNDLE 30s '"'"'+JSON.stringify({bad:CARD.nonFinite(),errs:CARD.ERRS,mode:CARD.ENGINE.AU.mode,hop:CARD.ENGINE.tex.hop,switched:CARD.SC.hist.length>1,help:[CARD.HELP.on,CARD.HELP.ticks]})"}]'); echo "$R" | grep EVAL | sed 's/.*=> //'; N=$(echo "$R" | grep -c '^\[EXC\]'); [ "$N" = 0 ] && echo "exceptions 0" || { echo "FAIL $N uncaught exceptions in the bundle"; echo "$R" | grep '^\[EXC\]' | head -1 | cut -c1-300; }
python3 tools/montage.py $OUT/montage-scenes.jpg 2 $OUT/s*-t6.jpg $OUT/s*-t14.jpg 2>/dev/null && echo "montage $OUT/montage-scenes.jpg"
